from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def add(id,title,creator,url,category,note,evidence,experiment,image='',origin='Added',tags=''):
 rows.append(dict(id=id,title=title,creator=creator,url=url,category=category,note=note,evidence=evidence,experiment=experiment,image=image,origin=origin,tags=tags,checked='2026-09-07'))
add('I01','Cosmic journey · Visual 581','Dimitri Thouzery / dith_idsgn','https://www.instagram.com/p/C3aoMWPtiKD/','Atmospheres','Pale filament-like structures against a deep black field. Explore density, negative space and slow spatial drift.','Caption names the work and tags TouchDesigner; exact node network is not disclosed.','Sprint 1 · Make three monochrome noise/displacement studies; keep speed and density independently adjustable.','dimitri.png','Yours','TouchDesigner monochrome cosmic generative')
add('I02','A cave, reimagined as splats','David Bewick / dave_bewick','https://www.instagram.com/p/DcazaTMJWT6/','Worlds','A cave appears tactile and unstable through selective focus and spatial distortion. The strongest bridge between your world-building and web interests.','Creator describes a Rydal cave scan, browser Gaussian-splat manipulation, depth of field, grain and audio response; tags Spark and Three.js. This is a creator claim, not an inspected implementation.','Sprints 4–6 · One splat scene, one camera movement, one controlled distortion.','bewick.png','Yours','Gaussian splat Spark Three.js cave audio')
add('I03','MUTEK Japan · selected stills','RICH & MIYU','https://www.instagram.com/p/DFmw64Pyulk/?img_index=1','Atmospheres','An owl and a mossy landscape broken into luminous, sparse spatial samples. Natural subjects become spectral without losing recognisability.','Caption explicitly says made in TouchDesigner and tags pointcloud; credits collaboration with @k__lc. First carousel image inspected; later slides remain to study.','Sprint 4 · Turn a simple original mesh into a sparse field; compare silhouette readability at three densities.','rich-miyu.png','Yours','TouchDesigner point cloud nature moss audiovisual')
add('I04','Immersive dome illusion','HuanYu AI Lab + Senseware','https://www.instagram.com/p/DbDPYsTCYwC/','Motion','Apparent audience-scale spectacle and a rushing overhead scene. Study viewpoint, scale and anticipation.','Post credits Senseware for technical support. Exact production method and whether the depicted event is real are unverified; video generation was the user’s hypothesis.','Optional motion study · Make a 5-second original scene with a single dramatic camera move; compare CGI and AI-video routes.','huanyu.png','Yours','dome immersive spectacle video uncertain')
add('I05','KNIGHT LIFE','Marco Sanalitro / marcosana.it','https://www.instagram.com/p/DZsD9CKo69T/','Objects','Armour, cold metal, close camera work and cinematic energy. Use the material and framing as a starting point before attempting a full character.','Caption explicitly credits Blender. Complete production pipeline is not available.','Sprints 2–3 · Design one armoured relic with three separable parts, then light and animate it.','knight.png','Yours','Blender CGI metal cinematic animation')
add('I06','Only humans, only forward','seanaiux','https://www.instagram.com/p/Dbvgfv4xFM3/','Web','Cinematic product imagery embedded in web layouts; the user specifically likes exploding components.','Creator says assets and wireframes in the examples are generated. The reel does not establish whether each shown layout is a functioning 3D website.','Sprints 3 + 6 · A 3-part artefact controlled by one explode slider, then connected to scroll.','sean.png','Yours','web generated assets exploded assembly product')
add('I07','Vectr · world-led landing page','Vectr / site credit: Utsubo','https://www.vectrfl.com/','Web','A pale miniature industrial world, restrained red accent and strong typography. The environment supports the story of the page.','Homepage visually inspected; footer credits Utsubo. Technical rendering stack not verified.','Sprint 6 · Compose three small structures around one camera path and one clear call to action.','vectr.png','Yours','web spatial miniature pale industrial')
add('I08','Utsubo · digital experiences','Utsubo','https://www.utsubo.com/','Web','Explore the studio behind Vectr for spatial storytelling and interaction pacing.','Vectr links to Utsubo. Studio describes web, games and interactive installations. Screenshot captures the entry screen only.','Study · Choose one interaction, record trigger → transition → end state, then prototype with primitives.','utsubo.png',tags='web interaction studio')
add('I09','A portfolio you drive through','Bruno Simon','https://bruno-simon.com/','Worlds','Use navigation itself as a way to discover work. Study landmarks, orientation and playful feedback.','Official site identifies Three.js and links source code, including Blender files. Text inspected; visual exploration is queued.','Sprint 6 · Place three exhibits with recognisable landmarks and a reset-camera control.',tags='Three.js Blender interactive portfolio navigation')
add('I10','Spark · programmable splat examples','World Labs','https://sparkjs.dev/','Worlds','A technical inspiration source for making scanned or generated worlds respond like living material.','Official documentation describes a Three.js Gaussian splat renderer and programmable effects.','Sprint 6 · Start with one official example, load one compatible splat and expose one effect parameter.',tags='Spark World Labs Gaussian splat Three.js')
add('I11','Marble · exportable worlds','World Labs','https://docs.worldlabs.ai/marble/export/specs','Worlds','Compare the same place as a panorama, a splat and a mesh. Each representation suggests a different artwork.','Official export specs list panorama, SPZ/PLY splats and collider/high-quality GLB meshes; account access not checked.','Sprint 5 · Compare three viewpoints and one export before committing to a larger world.',tags='Marble World Labs spatial export mesh')
add('I12','Machine Dreams / Dataland','Refik Anadol Studio','https://refikanadol.com/','Atmospheres','An adjacent research direction for AI art at architectural scale. Investigate how the audience encounters the work.','Official homepage identifies Machine Dreams: Rainforest and Dataland. Detailed work and methods are queued for closer study.','Study · Sketch a single-screen installation with a deliberately chosen viewing distance.',tags='AI installation environment data')
add('I13','TouchDesigner · learning by systems','Derivative','https://learn.derivative.ca/all-courses/','Learning','A modular resource to unlock the exact technique needed for the next piece.','Official curriculum includes TOPs, CHOPs, 3D rendering, scripting and points.','Sprints 0–4 · Use 101, 102 and 103 first; open later lessons only when the project needs them.',tags='TouchDesigner tutorials nodes')
add('I14','Meshy · object generation','Meshy','https://www.meshy.ai/','Learning','A fast source of original object candidates; evaluate all sides before committing to a render.','Official site describes text/image-to-3D and GLB exports. Access is user-confirmed; no generation performed.','Sprint 2 · One original isolated concept → one model → Blender cleanup and lighting.',tags='Meshy AI Blender asset GLB')
(ROOT/'inspiration/library.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
md='# Inspiration library\n\nCaptured 7 September 2026. All seven supplied URLs preserved. Screenshots are study captures with source credit, not reusable production assets. Video captures are representative frames, not archived videos. Interpretations and suggested experiments are ours; tool attribution is based on the creator or vendor where stated.\n\n'
for r in rows:
 md+=f"## {r['id']} · {r['title']}\n\n**{r['creator']}** · {r['origin']} · {r['category']}\n\n[Original source]({r['url']})\n\n{r['note']}\n\n**Evidence:** {r['evidence']}\n\n**Try:** {r['experiment']}\n\n"
 if r['image']: md+=f"![Study capture: {r['creator']}](images/{r['image']})\n\n"
(ROOT/'inspiration/library.md').write_text(md)
# Embed data so the board opens directly from disk without a server or dependencies.
data=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Spatial art lab — inspiration atlas</title><style>
:root{color-scheme:dark;--bg:#111310;--panel:#1b1e19;--line:#363d32;--muted:#b0b6a9;--ink:#f0f1e8;--accent:#d6f495}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}header,main,footer{max-width:1500px;margin:auto;padding:32px 5vw}header{padding-top:55px;border-bottom:1px solid var(--line)}.eyebrow{letter-spacing:.18em;text-transform:uppercase;font:12px monospace;color:var(--accent)}h1{font-size:clamp(42px,6vw,86px);line-height:1.04;font-weight:450;letter-spacing:-.065em;margin:22px 0}h2{font-weight:450;letter-spacing:-.03em;font-size:28px}p{color:var(--muted)}.intro{max-width:720px;font-size:18px}.topline,.controls,.links{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.topline{justify-content:space-between}a{color:var(--accent);text-underline-offset:4px}.routes{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:34px 0 10px}.route{border-top:1px solid var(--line);padding-top:14px}.route p{font-size:14px;margin:5px 0}.swatches{display:flex;margin:12px 0;gap:6px}.swatches i{height:8px;width:36px;background:var(--c)}button,input,select,textarea{font:inherit;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:5px;padding:10px 13px}button{cursor:pointer}button:hover{border-color:var(--accent)}button[aria-pressed=true]{background:var(--accent);color:#111310}input{flex:1;min-width:180px}textarea{width:100%;min-height:82px;resize:vertical}label{color:var(--muted)}:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.controls{position:sticky;top:0;background:var(--bg);z-index:2;padding:14px 0;border-bottom:1px solid var(--line)}#count{font:12px monospace;color:var(--muted);padding:15px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px}article{background:var(--panel);border:1px solid var(--line);overflow:hidden;border-radius:8px}.visual{display:block;height:275px;position:relative;overflow:hidden;background:#080b0c}.visual img{width:100%;height:100%;object-fit:cover}.visual .stamp{position:absolute;left:12px;bottom:10px;font:11px monospace;color:white;background:#101410dd;padding:4px 8px}.placeholder{height:220px;padding:28px;background:linear-gradient(145deg,#303c28,#101712);display:flex;flex-direction:column;justify-content:space-between}.placeholder strong{font-size:32px;font-weight:350;line-height:1.2}.placeholder span{font:11px monospace;color:var(--accent)}.body{padding:20px}.meta{font:11px monospace;text-transform:uppercase;letter-spacing:.06em;color:var(--accent)}h3{font-size:23px;line-height:1.25;font-weight:500;margin:12px 0 6px}.credit{font-size:13px;margin:0 0 14px}.body p{font-size:14px}.try{border-left:2px solid var(--accent);padding-left:12px}details{border-top:1px solid var(--line);margin-top:16px;padding-top:12px}summary{cursor:pointer;color:var(--muted);font-size:13px}.note{display:block;font-size:12px;margin:12px 0 5px}.cardbar{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:18px}.cardbar button{padding:6px 11px;font-size:12px}footer{border-top:1px solid var(--line);font-size:13px}.empty{padding:40px;color:var(--muted)}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid,.routes{grid-template-columns:1fr}.controls{position:static}.visual{height:310px}header,main,footer{padding:24px}h1{font-size:48px}}@media print{.controls,.cardbar button,textarea,#export{display:none}.grid{grid-template-columns:repeat(2,1fr)}article{break-inside:avoid}body{color:#111;background:white}p{color:#333}}
</style><header><div class="topline"><span class="eyebrow">Spatial art lab / reference atlas 001</span><span class="eyebrow">Started 07.09.2026</span></div><h1>Strange objects.<br>Living worlds.</h1><p class="intro">A growing collection for learning to make spatial artwork with AI. From spectral nature and cinematic objects to worlds you can enter and interfaces you can touch.</p><div class="links"><a href="../plans/learning-plan.md">Read the learning plan ↗</a><a href="library.md">Reference notebook ↗</a><a href="../experiments/001-cosmic-breath/brief.md">First experiment ↗</a></div><div class="routes"><div class="route"><span class="eyebrow">01 / Ghost ecologies</span><p>Monochrome, moss, dust, negative space.<br>TouchDesigner → signals → spatial fields.</p><div class="swatches"><i style="--c:#0b100d"></i><i style="--c:#656b5b"></i><i style="--c:#b1b391"></i><i style="--c:#e2ded0"></i></div></div><div class="route"><span class="eyebrow">02 / Impossible artefacts</span><p>Cold metal, physical detail, revealing structure.<br>AI concepts → Meshy → Blender.</p><div class="swatches"><i style="--c:#10191e"></i><i style="--c:#435560"></i><i style="--c:#a1b9c3"></i><i style="--c:#e3e9e8"></i></div></div><div class="route"><span class="eyebrow">03 / World as interface</span><p>Small worlds, deliberate cameras, clear interaction.<br>Marble / Blender → Three.js / Spark.</p><div class="swatches"><i style="--c:#d5dfe4"></i><i style="--c:#6e7a87"></i><i style="--c:#22252b"></i><i style="--c:#f57374"></i></div></div></div></header><main><div class="controls"><input id="search" aria-label="Search inspiration" placeholder="Search creator, mood, tool or technique…"><select id="category" aria-label="Filter by category"><option>All categories</option><option>Atmospheres</option><option>Objects</option><option>Motion</option><option>Worlds</option><option>Web</option><option>Learning</option></select><button id="yours" aria-pressed="false">Your references</button><button id="saved" aria-pressed="false">Shortlist</button><button id="export">Export notes</button></div><div id="count" role="status" aria-live="polite"></div><div id="grid" class="grid"></div></main><footer><p>Seven original references, plus seven adjacent sources and learning resources. Images are credited browser captures for this private study library. Open a capture to see the complete frame; open the source to watch the motion. Palettes and directions above are proposed interpretations.</p><p>Notes and shortlist are stored in this browser when storage is available. Export notes for a durable backup; they do not automatically update the project files. Source data: <a href="library.json">library.json</a>. To add references, use the capture template and ask Codex to update the seed records and rebuild the board.</p><span id="storageStatus"></span></footer><script>
const items=DATA;
const $=id=>document.getElementById(id);let state={};try{state=JSON.parse(localStorage.getItem('spatial-art-notes-v1')||'{}')}catch(e){$('storageStatus').textContent='Browser storage unavailable. Export notes before closing.'}let onlyYours=false,onlySaved=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('spatial-art-notes-v1',JSON.stringify(state))}catch(e){$('storageStatus').textContent='Could not save locally. Use Export notes.'}}
function draw(){const q=$('search').value.toLowerCase();const cat=$('category').value;let shown=items.filter(r=>(cat==='All categories'||r.category===cat)&&(!onlyYours||r.origin==='Yours')&&(!onlySaved||state[r.id]?.saved)&&Object.values(r).join(' ').toLowerCase().includes(q));$('count').textContent=shown.length+' / '+items.length+' references · click an image for the full capture';$('grid').innerHTML=shown.map(r=>`<article><${r.image?'a':'div'} ${r.image?`href="images/${esc(r.image)}" target="_blank" rel="noopener" class="visual"`:'class="placeholder"'}>${r.image?`<img src="images/${esc(r.image)}" alt="Study capture of ${esc(r.title)} by ${esc(r.creator)}" loading="lazy"><span class="stamp">${r.id} / STUDY CAPTURE ↗</span>`:`<span>${r.id} / LINK REFERENCE</span><strong>${esc(r.title)}</strong><span>Open source to explore ↗</span>`}</${r.image?'a':'div'}><div class="body"><div class="meta">${esc(r.category)} / ${r.origin==='Yours'?'Your inspiration':'Added to explore'}</div><h3>${esc(r.title)}</h3><p class="credit">${esc(r.creator)}</p><p>${esc(r.note)}</p><p class="try">${esc(r.experiment)}</p><details><summary>Evidence & personal notes</summary><p>${esc(r.evidence)}</p><p>Checked ${r.checked}. Tags: ${esc(r.tags)}</p><label class="note" for="note-${r.id}">What should we borrow, change or try?</label><textarea id="note-${r.id}" data-note="${r.id}" placeholder="Your observations…">${esc(state[r.id]?.note||'')}</textarea></details><div class="cardbar"><a href="${esc(r.url)}" target="_blank" rel="noopener">Open source ↗</a><button data-save="${r.id}" aria-pressed="${!!state[r.id]?.saved}">${state[r.id]?.saved?'Shortlisted ✓':'+ Shortlist'}</button></div></div></article>`).join('')||'<div class="empty">No matches. Try another term or clear the filters.</div>'}
$('search').addEventListener('input',draw);$('category').addEventListener('change',draw);$('yours').onclick=()=>{onlyYours=!onlyYours;$('yours').setAttribute('aria-pressed',onlyYours);draw()};$('saved').onclick=()=>{onlySaved=!onlySaved;$('saved').setAttribute('aria-pressed',onlySaved);draw()};$('grid').addEventListener('click',e=>{let b=e.target.closest('[data-save]');if(!b)return;let id=b.dataset.save;state[id]||={};state[id].saved=!state[id].saved;persist();draw()});$('grid').addEventListener('input',e=>{let id=e.target.dataset.note;if(!id)return;state[id]||={};state[id].note=e.target.value;persist()});$('export').onclick=()=>{const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),notes:state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spatial-art-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};draw();
</script></html>'''.replace('DATA',data)
(ROOT/'inspiration/index.html').write_text(page)
print(f'Built library with {len(rows)} references')
